#!/usr/bin/env python3
"""Package the tugmcp single-header release artifacts.

The script generates the three supported artifacts with ``tools/amalgamate.py``,
copies the third-party license texts that apply to the external headers, and
writes a deterministic ``SHA256SUMS`` plus ``NOTICE``/``README.md`` describing
the artifact matrix and consumption rules.

The output contains no timestamps: running the script twice with the same
inputs produces byte-identical files.

Usage:
    python tools/package_amalgamation.py --release-dir build/amalgamation/release
"""

from __future__ import annotations

import argparse
import hashlib
import importlib.util
import re
import shutil
import sys
from pathlib import Path
from typing import Dict, List, Sequence, Tuple

ROOT = Path(__file__).resolve().parents[1]
GENERATOR = ROOT / "tools" / "amalgamate.py"
LICENSES = ROOT / "LICENSES"
RECORDED_HASHES = ROOT / "tests" / "amalgamation"

PROJECT_VERSION = "0.1.0"
NLOHMANN_JSON_VERSION = "3.12.0"
NLOHMANN_JSON_COMMIT = "55f93686c01528224f448c19128836e7df245f72"
HTTPLIB_VERSION = "0.63.0"
# 3rd/README.md does not record a cpp-httplib upstream commit; the vendored
# header hash from cmake/verify_hashes.cmake is the reproducible identity.
HTTPLIB_FILE_SHA256 = (
    "9021001a719768893a8a6e4051c56107690e8b8e49b41e5f903534fa19ae9afb"
)

# (output name, amalgamate profile, tls, guard)
ARTIFACTS: Sequence[Tuple[str, str, bool, str]] = (
    ("tugmcp.hpp", "core", False, "TUGMCP_SINGLE_HEADER_CORE_HPP"),
    ("tugmcp_http.hpp", "http", False, "TUGMCP_SINGLE_HEADER_HTTP_HPP"),
    ("tugmcp_http_tls.hpp", "http", True, "TUGMCP_SINGLE_HEADER_HTTP_TLS_HPP"),
)

LICENSE_FILES = ("nlohmann-json-MIT.txt", "cpp-httplib-MIT.txt")

README = """\
# tugmcp single-header release artifacts

Project version: {project}

Generated by `tools/package_amalgamation.py` from the split headers in
`include/` and the implementation in `src/`. The split sources remain the source
of truth; never edit these headers by hand.

## Artifact matrix

| Header | Profile | Guard | External headers | Link requirements |
|---|---|---|---|---|
| `tugmcp.hpp` | core + stdio | `TUGMCP_SINGLE_HEADER_CORE_HPP` | `<nlohmann/json.hpp>` | `Threads::Threads` |
| `tugmcp_http.hpp` | core + stdio + Streamable HTTP/SSE (no TLS) | `TUGMCP_SINGLE_HEADER_HTTP_HPP` | `<nlohmann/json.hpp>`, `<httplib.h>` | `Threads::Threads`; `ws2_32` on Windows |
| `tugmcp_http_tls.hpp` | core + stdio + Streamable HTTP/SSE (TLS) | `TUGMCP_SINGLE_HEADER_HTTP_TLS_HPP` | `<nlohmann/json.hpp>`, `<httplib.h>` | `Threads::Threads`; `OpenSSL::SSL`/`OpenSSL::Crypto`; `ws2_32` + `crypt32` on Windows |

schema validator backends (jsoncons/Valijson) and the legacy HTTP+SSE transport
are intentionally excluded from every artifact.

## Consuming an artifact

Exactly **one** translation unit must define `TUGMCP_IMPLEMENTATION` before
including the header. Every other translation unit includes the same header
without that macro.

```cpp
// impl.cpp
#define TUGMCP_IMPLEMENTATION
#include "tugmcp_http.hpp"

// other.cpp
#include "tugmcp_http.hpp"
```

```cmake
# A consumer using the HTTP artifact on Windows.
target_link_libraries(app PRIVATE Threads::Threads ws2_32)
target_include_directories(app PRIVATE
  ${{TUGMCP_RELEASE_DIR}}
  ${{NLOHMANN_JSON_INCLUDE}}
  ${{CPP_HTTPLIB_INCLUDE}})
```

Link `Threads::Threads` for all artifacts. The HTTP artifact additionally needs
`ws2_32` on Windows and `<httplib.h>` on the include path. The TLS artifact
needs OpenSSL >= 3.0 (`OpenSSL::SSL`, `OpenSSL::Crypto`) and, on Windows,
`ws2_32` plus `crypt32`; cpp-httplib stays an external include and is not
embedded.

## TLS macro and ODR rule

The TLS artifact emits `TUGMCP_TLS_ENABLED=1` and defines
`CPPHTTPLIB_OPENSSL_SUPPORT` before `<httplib.h>`. Every translation unit that
sees `httplib.h` (directly or through `tugmcp_http_tls.hpp`) must use the same
macros. Never mix the TLS artifact with `tugmcp_http.hpp`/`tugmcp.hpp` in one
program or process, and do not define these macros differently per TU: the
result is an ODR violation that the linker cannot detect.

## Third-party dependencies and licenses

The artifacts keep third-party headers external:

- nlohmann/json {nlohmann_version} (upstream commit `{nlohmann_commit}`), MIT.
- cpp-httplib {httplib_version} (vendored header SHA256 `{httplib_sha}`), MIT.

Their license texts are bundled under `LICENSES/`. `SHA256SUMS` records the
hashes of the three headers and the bundled licenses. License texts are copied
verbatim from `LICENSES/` in the source tree.

## Regeneration

```bash
python tools/package_amalgamation.py --release-dir build/amalgamation/release
```

or, from a configured CMake build tree:

```bash
cmake --build build --target amalgamate-release
```

`cmake --build build --target amalgamate` only generates the three headers into
`build/amalgamation/` without packaging. Re-running either target with identical
inputs is byte-identical; `tests/amalgamation/run_release.py` and the
`amalgamation.release` ctest enforce this.
"""

NOTICE = """\
tugmcp single-header release artifacts
=====================================

Project:          tugmcp
Project version:  {project}

This directory contains generated single-header copies of the tugmcp C++17 MCP
library. The split headers in include/ and implementation in src/ remain the
source of truth.

Artifact matrix
---------------
tugmcp.hpp           core + stdio                         guard TUGMCP_SINGLE_HEADER_CORE_HPP
tugmcp_http.hpp      core + stdio + HTTP/SSE (no TLS)     guard TUGMCP_SINGLE_HEADER_HTTP_HPP
tugmcp_http_tls.hpp  core + stdio + HTTP/SSE (TLS)        guard TUGMCP_SINGLE_HEADER_HTTP_TLS_HPP

Excluded: jsoncons/Valijson schema backends and the legacy HTTP+SSE transport.

Third-party components (external headers, not embedded)
-------------------------------------------------------
nlohmann/json {nlohmann_version}
  upstream commit: {nlohmann_commit}
  license: MIT (LICENSES/nlohmann-json-MIT.txt)

cpp-httplib {httplib_version}
  vendored header SHA256: {httplib_sha}
  license: MIT (LICENSES/cpp-httplib-MIT.txt)

tugmcp itself is distributed under the terms of this project. See the project
repository for its license.

Consumption summary
-------------------
Define TUGMCP_IMPLEMENTATION in exactly one translation unit before including a
header; include it without the macro everywhere else. Link Threads::Threads.
HTTP adds ws2_32 on Windows; TLS adds OpenSSL >= 3.0 and, on Windows, ws2_32 +
crypt32. All TUs must agree on TUGMCP_TLS_ENABLED and CPPHTTPLIB_OPENSSL_SUPPORT.

Integrity
---------
SHA256SUMS lists the hashes of the generated headers and bundled licenses.
"""


class PackagingError(RuntimeError):
    pass


def sha256_bytes(payload: bytes) -> str:
    return hashlib.sha256(payload).hexdigest()


def sha256_file(path: Path) -> str:
    return sha256_bytes(path.read_bytes())


def load_generator():
    spec = importlib.util.spec_from_file_location(
        "tugmcp_amalgamate", GENERATOR
    )
    if spec is None or spec.loader is None:
        raise PackagingError(f"cannot load generator: {GENERATOR}")
    module = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(module)
    return module


def write_bytes(path: Path, payload: bytes) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_bytes(payload)


def write_text(path: Path, text: str) -> None:
    write_bytes(path, text.encode("utf-8"))


def read_recorded_hash(name: str) -> str:
    path = RECORDED_HASHES / name
    if not path.is_file():
        raise PackagingError(f"recorded hash file not found: {path}")
    tokens = path.read_text(encoding="utf-8").split()
    if not tokens or not re.fullmatch(r"[0-9a-fA-F]{64}", tokens[0]):
        raise PackagingError(f"recorded hash file is malformed: {path}")
    return tokens[0].lower()


def generate_artifacts(release_dir: Path, verify_hashes: bool) -> Dict[str, str]:
    module = load_generator()
    hashes: Dict[str, str] = {}
    for name, profile, tls, _guard in ARTIFACTS:
        try:
            text = module.generate(profile, tls)
        except module.GenerationError as error:
            raise PackagingError(f"cannot generate {name}: {error}") from error
        payload = text.encode("utf-8")
        digest = sha256_bytes(payload)
        key = "http_tls" if profile == "http" and tls else profile
        if verify_hashes:
            recorded = read_recorded_hash(f"{key}.sha256")
            if digest != recorded:
                raise PackagingError(
                    f"{name} does not match the recorded hash:\n"
                    f"  recorded: {recorded}\n"
                    f"  generated: {digest}\n"
                    "Regenerate tests/amalgamation/*.sha256 if the change is "
                    "intentional."
                )
        write_bytes(release_dir / name, payload)
        hashes[name] = digest
    return hashes


def copy_licenses(release_dir: Path) -> Dict[str, str]:
    hashes: Dict[str, str] = {}
    target_dir = release_dir / "LICENSES"
    for name in LICENSE_FILES:
        source = LICENSES / name
        if not source.is_file():
            raise PackagingError(f"license file not found: {source}")
        payload = source.read_bytes()
        write_bytes(target_dir / name, payload)
        hashes[f"LICENSES/{name}"] = sha256_bytes(payload)
    return hashes


def write_sums(release_dir: Path, hashes: Dict[str, str]) -> None:
    lines = [
        f"{hashes[name]}  {name}" for name in sorted(hashes)
    ]
    write_text(release_dir / "SHA256SUMS", "\n".join(lines) + "\n")


def package(release_dir: Path, verify_hashes: bool = True) -> Dict[str, str]:
    release_dir.mkdir(parents=True, exist_ok=True)
    # Remove files this script owns so a stale artefact cannot survive.
    for name, _profile, _tls, _guard in ARTIFACTS:
        (release_dir / name).unlink(missing_ok=True)
    for name in ("SHA256SUMS", "NOTICE", "README.md"):
        (release_dir / name).unlink(missing_ok=True)
    shutil.rmtree(release_dir / "LICENSES", ignore_errors=True)

    hashes = generate_artifacts(release_dir, verify_hashes)
    license_hashes = copy_licenses(release_dir)

    notice = NOTICE.format(
        project=PROJECT_VERSION,
        nlohmann_version=NLOHMANN_JSON_VERSION,
        nlohmann_commit=NLOHMANN_JSON_COMMIT,
        httplib_version=HTTPLIB_VERSION,
        httplib_sha=HTTPLIB_FILE_SHA256,
    )
    readme = README.format(
        project=PROJECT_VERSION,
        nlohmann_version=NLOHMANN_JSON_VERSION,
        nlohmann_commit=NLOHMANN_JSON_COMMIT,
        httplib_version=HTTPLIB_VERSION,
        httplib_sha=HTTPLIB_FILE_SHA256,
    )
    write_text(release_dir / "NOTICE", notice)
    write_text(release_dir / "README.md", readme)

    # Hash the headers and licenses only: README/NOTICE are descriptive and
    # their own hashes would make SHA256SUMS self-referential to edit.
    write_sums(release_dir, {**hashes, **license_hashes})
    return hashes


def main(argv: Sequence[str] | None = None) -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument(
        "--release-dir",
        type=Path,
        default=ROOT / "build" / "amalgamation" / "release",
        help="output directory (default: build/amalgamation/release)",
    )
    parser.add_argument(
        "--skip-hash-check",
        action="store_true",
        help="do not compare against tests/amalgamation/*.sha256",
    )
    args = parser.parse_args(list(argv) if argv is not None else None)

    release_dir = args.release_dir.resolve()
    try:
        hashes = package(release_dir, verify_hashes=not args.skip_hash_check)
    except PackagingError as error:
        print(f"package_amalgamation: error: {error}", file=sys.stderr)
        return 1

    print(f"package_amalgamation: wrote {release_dir}")
    for name, _profile, _tls, _guard in ARTIFACTS:
        size = (release_dir / name).stat().st_size
        print(f"  {name}  {size} bytes  {hashes[name]}")
    print(f"  SHA256SUMS, NOTICE, README.md, LICENSES/"
          f"{{{','.join(LICENSE_FILES)}}}")
    return 0


if __name__ == "__main__":
    sys.exit(main())
